const posts = await Post.findAll({ limit: 200 });      // 쿼리 1
for (const p of posts) {
  p.authorName = (await User.findByPk(p.userId)).name;  // 쿼리 200
}
// 총 201 쿼리 · 각 2ms 여도 400ms
// 게다가 DB 가 아니라 왕복 지연이 대부분이라 서버 CPU 는 한가해 보인다

// ① 미리 함께 가져오기 (eager loading)
await Post.findAll({ include: [User], limit: 200 });     // 조인 1번

// ② 한 번에 모아서 조회 (IN)
const ids = [...new Set(posts.map(p => p.userId))];
const users = await User.findAll({ where: { id: ids } }); // 쿼리 2번
const map = new Map(users.map(u => [u.id, u]));

// ③ DataLoader 류 — 같은 틱의 조회를 자동으로 묶는다 (GraphQL 에서 표준)

// 요청당 쿼리 수를 세고 문턱을 넘으면 경고/실패
let 쿼리수 = 0;
db.on('query', () => 쿼리수++);

afterRequest(() => {
  if (쿼리수 > 20) log.warn(`쿼리 폭발: ${경로} — ${쿼리수}개`);
});

// 테스트에서는 아예 실패시켜라
